mapper.select:
SELECT gc.common_id, gc.goods_id, gc.common_name, gc.common_price, gc.common_market_price, gc.common_image, gc.common_salenum, gc.common_promotion_tips, gc.common_evaluate, gc.common_collect, gc.shop_id, gc.shop_name, gc.common_is_xian, sb.shop_self_support FROM ${database.prefix.goods}hou_goods_common gc LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON gc.shop_id = sb.supplier_shop_id WHERE sb.shop_status = 3 AND common_state = 1 AND common_verify = 1 AND goods_type = 1 AND integral_goods != 0
and cat_id = #{param.catId,jdbcType=INTEGER}
and cat_id in
#{catId}
ORDER BY common_collect,common_evaluate,common_salenum desc limit 4

select
from ${database.prefix.goods}hou_goods_base gb left join ${database.prefix.goods}hou_goods_common gc on gb.common_id = gc.common_id left join ${database.prefix.supplier}hou_shop_base sb on gb.shop_id = sb.supplier_shop_id where goods_is_shelves =1 and gb.goods_id in
#{goodId}

SELECT DISTINCT ( b.supplier_shop_id ), b.shop_name, b.shop_collect, b.shop_slide, b.wap_shop_logo, b.shop_logo, b.district_id, b.shop_self_support FROM ${database.prefix.supplier}hou_shop_base b, ${database.prefix.goods}hou_goods_common a WHERE a.shop_id = b.supplier_shop_id AND b.shop_status = 3 AND a.common_state = 1 AND a.common_verify = 1 AND b.shop_type != 3
and b.shop_type = #{param.shopType}
and b.shop_name LIKE CONCAT('%',#{param.shopName },'%')
and b.shop_self_support = #{param.shopSelfSupport,jdbcType=VARCHAR}
and b.district_id in (
#{districtId}
)
ORDER BY b.shop_collect,b.shop_grade_id desc
ORDER BY b.shop_collect desc
